import type { NextConfig } from "next";

// Content-Security-Policy: moderate, integration-aware. Uses 'unsafe-inline'
// (no nonce infra yet) but still adds real protections — object-src none,
// base-uri/form-action self, frame-ancestors none, and script/frame allowlists
// for Stripe + analytics. connect-src is permissive to keep the console (wss)
// and API integrations working.
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  // PayPal's JS SDK (loaded by @paypal/react-paypal-js on the embedded Payment
  // step) both executes a script from paypal.com/paypalobjects.com AND opens an
  // in-page iframe from the same origins for the button + approval flow — found
  // by actually loading the page in a real browser (Playwright) during the
  // embedded-payment-UI build, where the button silently failed to render with
  // nothing but a CSP violation in the console. Sandbox's domain is included too
  // so a `PAYPAL_MODE=sandbox` testing session isn't the ONE environment this
  // never got exercised in.
  // connect.facebook.net = Meta Pixel (fbevents.js); googleads.g.doubleclick.net +
  // www.googleadservices.com = Google Ads conversion/remarketing tags. Both were
  // blocked on every page until 2026-09-27, so browser-side Pixel and Ads
  // tracking never fired (server-side CAPI / offline upload were unaffected).
  "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://plausible.io https://*.googletagmanager.com https://www.google-analytics.com https://js.stripe.com https://www.paypal.com https://www.paypalobjects.com https://www.sandbox.paypal.com https://connect.facebook.net https://googleads.g.doubleclick.net https://www.googleadservices.com",
  "connect-src 'self' https: wss:",
  // blob: lets the webmail render an email body in a sandboxed blob:-URL iframe
  // (a `srcdoc` frame loads as about:srcdoc, which this frame-src refuses). The
  // frame stays fully sandboxed and inherits the rest of this CSP.
  "frame-src 'self' blob: https://js.stripe.com https://hooks.stripe.com https://www.paypal.com https://www.sandbox.paypal.com https://td.doubleclick.net https://www.googletagmanager.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  "upgrade-insecure-requests",
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Content-Type-Options", value: "nosniff" },
  // NOTE: X-Frame-Options is intentionally NOT set here — nginx already sends it,
  // and two conflicting values (DENY vs SAMEORIGIN) is undefined behaviour.
  // CSP `frame-ancestors 'none'` above is the authoritative, stricter control.
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // microphone=(self): the Matrix build console offers voice-to-text (Web Speech
  // API), which the browser gates on the microphone permission policy. A bare
  // microphone=() disables the mic for the whole origin, so the mic button did
  // nothing at all. (self) grants it to our own pages only — third-party frames
  // still can't use it. camera/geolocation stay fully disabled (never used).
  { key: "Permissions-Policy", value: "camera=(), microphone=(self), geolocation=(), interest-cohort=()" },
  { key: "X-DNS-Prefetch-Control", value: "on" },
];

const nextConfig: NextConfig = {
  // Frozen at build time so the sitemap can report a STABLE <lastmod> for the
  // routes that aren't row-backed. app/sitemap.ts used `new Date()`, which
  // (the route being force-dynamic) told Google every one of ~47,000 URLs had
  // just changed on every single crawl. See that file for the full note.
  env: { BUILD_TIME: new Date().toISOString() },

  // No `images.remotePatterns` here on purpose. NxLabs (app/(marketing)/mods,
  // app/dashboard/nxlabs) renders mod icons from whichever source verified
  // them (cdn.modrinth.com, spigotmc.org, gcdn.thunderstore.io — and more as
  // scripts/verify-gamemods.ts grows to cover other sources), which would mean
  // maintaining an allowlist that grows every time a new source is wired up.
  // Those pages use plain <img> tags instead — the CSP's `img-src https:`
  // already permits any https host, confirmed rendering real icons in a real
  // browser. next/image stays the default everywhere else in this app.
  // The dev overlay sits bottom-left, exactly on top of the sidebar's account
  // balance card, which makes the design impossible to compare against the
  // reference. Sandbox only — prod never sets NXEON_SANDBOX.
  ...(process.env.NXEON_SANDBOX === "1" ? { devIndicators: false as const } : {}),
  output: "standalone",
  // ssh2 (and its SFTP wrapper) ship an OPTIONAL native addon (sshcrypto.node).
  // When the toolchain is present at install time npm builds that binary, and
  // webpack then fails trying to parse it into the server bundle. These are
  // server-only modules, so mark them external — Next require()s them at runtime
  // instead of bundling, which is the correct treatment for a native addon and
  // is behaviour-neutral (falls back to ssh2's pure-JS crypto when unbuilt).
  // pdfkit resolves its built-in font metrics (`js/data/*.afm`) relative to its
  // own file location. Bundled, that becomes `.next/server/chunks/data/` — which
  // no build ever writes — so every emailed invoice lost its PDF with
  // `ENOENT ... chunks/data/Helvetica.afm` while the email itself still sent.
  // External keeps the require at runtime, so it finds its own data dir. Same
  // reason geoip-lite is here: a package that reads data files off its own path
  // cannot be bundled.
  // playwright is here for the same reason: it resolves its browser binaries off
  // its own installation path at runtime (~/.cache/ms-playwright), so bundling it
  // breaks the lookup. It is `await import()`ed, and only ever from the hosting
  // website-preview capture (lib/hosting-thumb.ts) — nothing on a request path
  // loads it, so an environment with no browser installed simply fails that one
  // task with a real error instead of affecting the app.
  serverExternalPackages: ["@prisma/client", "bcryptjs", "ssh2", "ssh2-sftp-client", "geoip-lite", "pdfkit", "playwright"],
  experimental: {
    // Webmail attachments travel through a Server Action as base64, and Next's
    // default Server Action body limit is 1 MB. Base64 inflates by ~4/3, so
    // anything over roughly 700 KB was rejected by the framework before our
    // handler ever ran — while both the composer
    // (components/customer/mail/Composer.tsx) and the server
    // (lib/actions-mail.ts MAX_ATTACHMENTS_TOTAL_BYTES) advertised 20 MB.
    // Customers attached a 2 MB PDF and the mail silently failed to send.
    // 20 MB of files encodes to ~26.7 MB; 30 MB leaves headroom for the rest of
    // the payload (recipients, subject, HTML body). lib/actions-mail.ts still
    // enforces the real 20 MB cap, with a message the customer can act on.
    serverActions: { bodySizeLimit: "30mb" },
    // Same class of bug as the serverActions limit above, a different layer:
    // middleware.ts's matcher covers virtually every path (including
    // /api/files/[serverId]'s upload route), and Next.js caps the request
    // body it will forward THROUGH middleware at 10MB by default —
    // independent of both nginx's client_max_body_size and the route
    // handler's own MAX_UPLOAD_BYTES check, which never even got a chance to
    // run: the body was already truncated to 10MB before either of those
    // layers saw it. Found live 2026-09-06 via a real production log line
    // ("Request body exceeded 10MB for /api/files/...") after nginx's size
    // limit and client_body_timeout were both already fixed and still didn't
    // resolve the customer's upload failure — this was the actual, complete
    // cause. Matches the app's own 250MB upload limit + margin.
    middlewareClientMaxBodySize: "260mb",
